import CredentialKit
import Foundation

/// Apple's public certification authority certificates (WWDR intermediates and roots), embedded as data.
/// They contain no secrets. Source: the system keychains of a macOS install (Apple Inc. PKI).
/// Used only to complete a leaf-only signing chain the way Xcode's codesign does; iOS decides trust.
enum AppleCertificateAuthorities {
    private static let base64: [(name: String, der: String)] = [
        ("Apple Root CA - G3", ""),
        ("Apple Root CA", ""),
        ("Apple Root CA - G2", ""),
        ("WWDR G3", ""),
        ("WWDR G6", ""),
    ]

    static let all: [Data] = base64.compactMap { Data(base64Encoded: $0.der) }

    /// Appends issuers from the embedded list until a self-signed certificate (the root) or no issuer is known.
    static func complete(chain: [Data]) -> [Data] {
        var result = chain
        for _ in 0..<4 {
            guard let last = result.last, let names = subjectAndIssuer(last), names.subject != names.issuer else { break }
            guard let parent = all.first(where: { subjectAndIssuer($0)?.subject == names.issuer }) else { break }
            if result.contains(parent) { break }
            result.append(parent)
        }
        return result
    }

    private static func subjectAndIssuer(_ der: Data) -> (subject: Data, issuer: Data)? {
        guard let cert = try? ASN1.parse(der), let tbs = try? cert.children().first, var f = try? tbs.children() else { return nil }
        if f.first?.tag == 0xA0 { f.removeFirst() }
        guard f.count >= 5 else { return nil }
        return (f[4].encoded, f[2].encoded)   // subject, issuer
    }
}
